package net.civeira.phylax.feature.observe.observedissue.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.valueobject.LastTraceIdVO;

class LastTraceIdValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of last trace id of observed issue")
  void test_last_trace_id_value_holder_assign_plain_value() {
    Object holder = new Object();
    LastTraceIdValueHolder<Object> value = new LastTraceIdValueHolder<>(holder);
    Assertions.assertSame(holder, value.lastTraceId("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getLastTraceIdValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getLastTraceId().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.lastTraceIdNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getLastTraceIdValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getLastTraceId().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of last trace id of observed issue")
  void test_last_trace_id_value_holder_assign_value_object() {
    Object holder = new Object();
    LastTraceIdValueHolder<Object> value = new LastTraceIdValueHolder<>(holder);
    LastTraceIdVO vo = LastTraceIdVO.from("one");
    Assertions.assertFalse(value.getLastTraceIdValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.lastTraceId(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getLastTraceIdValue().orElseThrow());
    Assertions.assertSame(holder, value.lastTraceId(Optional.empty()));
    Assertions.assertFalse(value.getLastTraceIdValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.lastTraceId(Optional.of(vo)));
    Assertions.assertSame(vo, value.getLastTraceIdValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of last trace id of observed issue against the original")
  void test_last_trace_id_value_holder_read() {
    Object holder = new Object();
    LastTraceIdValueHolder<Object> value = new LastTraceIdValueHolder<>(holder);
    LastTraceIdVO vo = LastTraceIdVO.from("one");
    LastTraceIdVO other = LastTraceIdVO.from("one");
    ObservedIssue original = Mockito.mock(ObservedIssue.class);
    Mockito.when(original.getLastTraceIdValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readLastTraceId(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readLastTraceId(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.lastTraceId(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readLastTraceId(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readLastTraceId(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of last trace id of observed issue")
  void test_last_trace_id_value_holder_unset() {
    Object holder = new Object();
    LastTraceIdValueHolder<Object> value = new LastTraceIdValueHolder<>(holder);
    LastTraceIdVO vo = LastTraceIdVO.from("one");
    value.lastTraceId(vo);
    Assertions.assertSame(holder, value.unsetLastTraceIdIfMatches("lastTraceId_other"));
    Assertions.assertTrue(value.getLastTraceIdValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetLastTraceIdIfMatches("lastTraceId"));
    Assertions.assertFalse(value.getLastTraceIdValue().isPresent(),
        "The field name must clear the value");
    value.lastTraceId(vo);
    Assertions.assertSame(holder, value.unsetLastTraceId());
    Assertions.assertFalse(value.getLastTraceIdValue().isPresent(), "Unset must clear the value");
  }
}
